def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit from s_in to s_out."""
    # Simple approach: find first differing character position
    pos = -1
    for i, (c1, c2) in enumerate(zip(s_in, s_out)):
        if c1 != c2:
            pos = i
            break

    # If strings are different lengths, we need to handle insertion/deletion
    if pos == -1:
        if len(s_in) != len(s_out):
            pos = min(len(s_in), len(s_out))
        else:
            return None  # No difference

    # Find what needs to change
    if len(s_in) > len(s_out):
        # Deletion case
        old_sub = s_in[pos]
        new_sub = ""
    elif len(s_in) < len(s_out):
        # Insertion case  
        old_sub = ""
        new_sub = s_out[pos]
    else:
        # Substitution case
        old_sub = s_in[pos]
        new_sub = s_out[pos]

    return (old_sub, new_sub, pos)

def propose_rule_candidates(s_in, s_out):
    """Propose rule candidates from a change."""
    # This is a simplified version for our purposes
    # In real implementation, it would be more sophisticated
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)
    if old_sub is None:
        return []
    return [(old_sub, new_sub)]

def apply_rules(strings, rules):
    """Apply a sequence of rules to strings."""
    result = strings[:]
    for pattern, replacement in rules:
        result = [s.replace(pattern, replacement) for s in result]
    return result

def score_rules(inputs, outputs, rules):
    """Score how well rules match the input/output pairs."""
    result = apply_rules(inputs, rules)
    correct = sum(1 for i, o in zip(result, outputs) if i == o)
    return correct / len(outputs)

def find_over_applications(inputs, outputs, rules):
    """Find inputs that would be incorrectly modified by rules."""
    result = apply_rules(inputs, rules)
    over_apps = []
    for i, (inp, outp, res) in enumerate(zip(inputs, outputs, result)):
        if res != outp and inp != outp:  # Only flag cases where input != output
            over_apps.append((i, inp, res))
    return over_apps

